func deepMerge(_ a: Any, _ b: Any) -> Any {
    switch (a, b) {
    case let (dictA as [String: Any], dictB as [String: Any]):
        var result = dictA
        for (key, value) in dictB {
            if let existing = result[key] {
                result[key] = deepMerge(existing, value)
            } else {
                result[key] = value
            }
        }
        return result
    case let (arrA as [Any], arrB as [Any]):
        var result = arrA
        for item in arrB {
            if !containsEquivalent(result, item) {
                result.append(item)
            }
        }
        return result
    default:
        return b
    }
}

func containsEquivalent(_ array: [Any], _ item: Any) -> Bool {
    for existing in array {
        if areEquivalent(existing, item) {
            return true
        }
    }
    return false
}

