fn format_currency(value: f64, decimals: u32) -> String {
    let s = if decimals == 0 {
        format!("{:.0}", value)
    } else {
        format!("{:.2}", value)
    };

    let mut result = String::new();
    let mut count = 0;
    let mut first = true;

    for c in s.chars().rev() {
        if c == '.' {
            result.push('.');
            first = false;
        } else {
            if !first && count > 0 && count % 3 == 0 {
                result.push(',');
            }
            result.push(c);
            count += 1;
            first = false;
        }
    }

    result.chars().rev().collect()
}

