enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn get(&self, key: &str) -> Option<&JsonValue> {
        match self {
            JsonValue::Object(pairs) => pairs.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    fn as_array(&self) -> Option<&Vec<JsonValue>> {
        match self { JsonValue::Array(arr) => Some(arr), _ => None }
    }
}

fn parse_json(s: &str) -> Result<JsonValue, String> {
    let mut chars = s.chars().peekable();
    parse_value(&mut chars)
}

fn skip_whitespace(chars: &mut std::iter::Peekable<std::str::Chars>) {
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() { chars.next(); } else { break; }
    }
}

fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<JsonValue, String> {
    skip_whitespace(chars);
    match chars.peek() {
        Some(&'"') => parse_string(chars).map(JsonValue::Str),
        Some(&'{') => parse_object(chars),
        Some(&'[') => parse_array(chars),
        Some(&'t') | Some(&'f') | Some(&'n') => parse_literal(chars),
        Some(&c) if c == '-' || c.is_ascii_digit() => parse_number(chars),
        _ => Err(format!("Unexpected character: {:?}", chars.peek())),
    }
}

