} FileInfo;

static FileInfo *files = NULL;
static int file_count = 0;
static int file_capacity = 0;

static void ensure_capacity(void) {
    if (file_count >= file_capacity) {
        file_capacity = file_capacity == 0 ? 16 : file_capacity * 2;
        FileInfo *new_files = realloc(files, file_capacity * sizeof(FileInfo));
        if (new_files) files = new_files;
    }
}

static void add_file(const char *full_path) {
    ensure_capacity();
    FileInfo *f = &files[file_count];

    const char *rel = full_path + strlen(BASE_DIR);
    if (*rel == '/') rel++;
    f->path = malloc(strlen(rel) + 1);
    strcpy(f->path, rel);

    const char *dot = strrchr(f->path, '.');
    if (dot) {
        f->ext = malloc(strlen(dot) + 1);
        strcpy(f->ext, dot);
    } else {
        f->ext = malloc(1);
        f->ext[0] = '\0';
    }

    FILE *fp = fopen(full_path, "rb");
    if (fp) {
        f->chars = 0;
        f->lines = 0;
        char buf[4096];
        size_t n;
        while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) {
            f->chars += n;
            for (size_t k = 0; k < n; k++) {
                if (buf[k] == '\n') f->lines++;
            }
        }
        fclose(fp);
    } else {
        f->chars = 0;
        f->lines = 0;
    }

    file_count++;
}

