char* run_command(const char* cmd) {
    FILE* pipe = popen(cmd, "r");
    if (!pipe) return NULL;

    size_t capacity = 4096;
    char* buffer = malloc(capacity);
    if (!buffer) {
        pclose(pipe);
        return NULL;
    }

    size_t pos = 0;
    size_t nread;

    while ((nread = fread(buffer + pos, 1, capacity - pos - 1, pipe)) > 0) {
        pos += nread;
        if (pos >= capacity - 1) {
            capacity *= 2;
            char* tmp = realloc(buffer, capacity);
            if (!tmp) {
                free(buffer);
                pclose(pipe);
                return NULL;
            }
            buffer = tmp;
        }
    }

    pclose(pipe);

    while (pos > 0 && (buffer[pos-1] == '\n' || buffer[pos-1] == '\r' || buffer[pos-1] == ' ' || buffer[pos-1] == '\t')) {
        pos--;
    }
    buffer[pos] = '\0';

    return buffer;
}

char* json_escape(const char* str) {
    size_t len = strlen(str);
    size_t extra = 0;
    for (size_t i = 0; i < len; i++) {
        if (str[i] == '"' || str[i] == '\\' || str[i] == '\n' || str[i] == '\r' || str[i] == '\t') {
            extra++;
        }
    }

    size_t new_len = len + extra + 1;
    char* escaped = malloc(new_len);
    if (!escaped) return NULL;

    size_t j = 0;
    for (size_t i = 0; i < len; i++) {
        switch (str[i]) {
            case '"': escaped[j++] = '\\'; escaped[j++] = '"'; break;
            case '\\': escaped[j++] = '\\'; escaped[j++] = '\\'; break;
            case '\n': escaped[j++] = '\\'; escaped[j++] = 'n'; break;
            case '\r': escaped[j++] = '\\'; escaped[j++] = 'r'; break;
            case '\t': escaped[j++] = '\\'; escaped[j++] = 't'; break;
            default: escaped[j++] = str[i]; break;
        }
    }
    escaped[j] = '\0';
    return escaped;
}

