    printf("Matrix A:\n");
    print_matrix(mA);
    printf("\nMatrix B:\n");
    print_matrix(mB);
    printf("\nA x B =\n");
    print_matrix(mC);
    printf("\nDeterminant: %d\n", determinant(mC));

    free_matrix(mA, N);
    free_matrix(mB, N);
    free_matrix(mC, N);

    return 0;
}

