// Multiplication
func multiply(_ M1: [[Int]], _ M2: [[Int]]) -> [[Int]] {
    let rows = M1.count
    let cols = M2[0].count
    var result = Array(repeating: Array(repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            var sum = 0
            for k in 0..<M1[0].count {
                sum += M1[i][k] * M2[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

// Determinant (3x3 only)
func determinant(_ M: [[Int]]) -> Int {
    // M is 3x3
    let a = M[0][0]
    let b = M[0][1]
    let c = M[0][2]
    let d = M[1][0]
    let e = M[1][1]
    let f = M[1][2]
    let g = M[2][0]
    let h = M[2][1]
    let i = M[2][2]

    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

