func padLeft(_ value: Int, width: Int) -> String {
    let s = String(value)
    if s.count >= width { return s }
    var result = ""
    for _ in 0..<(width - s.count) {
        result += " "
    }
    result += s
    return result
}

func printMatrixRows(_ M: [[Int]], label: String) {
